script:
let download_veiw_employee = root_element.querySelector("#download_veiw_employee");

if (download_veiw_employee) {
    download_veiw_employee.addEventListener("click", () => {
        frappe.set_route("query-report", "Distributor Report");
    });
}

/* ---------- CONFIG / ELEMENTS ---------- */
let distributorInfo = [
    { title: "Sr. No.", name: "sr_no" },
    { title: "Distributor Name", name: "distributor_name" },
    { title: "Distributor Contact", name: "distributor_contact_number" },
    { title: "Distributor Meril Company Table" , name: "divisions_meril_company_names"},
    { title: "Attendee Name", name: "attendee_name" },
    { title: "Designation", name: "designation" },
    { title: "Distributor Company", name: "distributor_company_name" },
    { title: "Distributor Company Address", name: "distributor_company_address" },
    { title: "Account Distributor Code", name: "account_distributor_code" },
    { title: "RSM/State Head", name: "distributor_rsm_state_head" },
    { title: "BU/FD Head", name: "distributor_bu__fd_head" },
    { title: "Country", name: "country" },
    { title: "City", name: "city" },
    { title: "Region", name: "region" },
    { title: "State", name: "state" },
    { title: "Course Name", name: "course_name" },
    { title: "Login Remainder Sended", name: "login_remainer_count" },
    { title: "Course Remainder Sended", name: "course_reminder_count" },
    { title: "Course Status", name: "completion_status" },
    { title: "Re-enrollments", name: "re_enrollment_count" },
    { title: "Documents Status", name: "submitted_documents" },
    { title: "Send Initial Notification", name: "distributor_user_id" },
    { title: "Course Timeline", name: "enrollment_history" }
];

const table = root_element.querySelector('.distributor_table');
const thead = table ? table.querySelector('thead') : null;
const heading_container = thead ? thead.querySelector('.heading_container') : null;
const distributor_table_body = root_element.querySelector('.distributor_table_body');

let currentPage = 1;
let rowsPerPage = 5;
let distributorsData = [];
let filteredData = [];


/* ---------- LOADING & ERROR ELEMENTS ---------- */
const statusRow = document.createElement("tr");
statusRow.classList.add("status-row");

const statusCell = document.createElement("td");
statusCell.colSpan = distributorInfo.length;
statusCell.classList.add("text-center", "py-3", "fw-bold");
statusRow.appendChild(statusCell);

/* ---------- RENDER HEADERS + FILTER ROW ---------- */
function render_titles() {
    if (!heading_container || !thead) return;

    heading_container.innerHTML = '';
    distributorInfo.forEach(info => {
        const th = document.createElement('th');
        th.innerText = info.title;
        heading_container.appendChild(th);
    });

    const existing = thead.querySelector('.filter-row');
    if (existing) existing.remove();

    const filterRow = document.createElement('tr');
    filterRow.classList.add('filter-row');

    distributorInfo.forEach(info => {
        const fc = document.createElement('th');
        if (info.name !== 'sr_no') {
            const input = document.createElement('input');
            input.type = 'text';
            input.placeholder = 'Filter...';
            input.className = "form-control form-control-sm column-filter";
            input.dataset.field = info.name;
            input.addEventListener('input', debounce(applyFilters, 200));
            fc.appendChild(input);
        }
        filterRow.appendChild(fc);
    });

    thead.appendChild(filterRow);
}
render_titles();

/*------------ Rows Per Page (Distributor)-----------*/
let rowsPerPageDistributorSelect = root_element.querySelector("#rowsPerPageDistributor");

rowsPerPageDistributorSelect.addEventListener("change", () => {
    if (rowsPerPageDistributorSelect.value === "All") {
        rowsPerPage = filteredData.length;
    } else {
        rowsPerPage = parseInt(rowsPerPageDistributorSelect.value);
    }
    currentPage = 1;
    renderCurrentPage();
});

/* ---------- REFRESH (server call) ---------- */
const refreshButton = root_element.querySelector("button#refresh");
refreshButton && refreshButton.addEventListener("click", RefreshData);

function RefreshData() {
    showStatus("Fetching data, please wait...", "loading");

    frappe.call({
        method: "lms.overrides.dashboardapi.get_distributor_dashboard_info",
        callback: function (response) {
            if (response.message) {
                distributorsData = Array.isArray(response.message) ? response.message : [];
                filteredData = [...distributorsData];
                currentPage = 1;
                applySorting();
                renderCurrentPage();
            } else {
                showStatus("Error: No data returned from server", "error");
                console.error("Error calling whitelisted method:", response);
            }
        },
        error: function (err) {
            showStatus("Error fetching data. Please try again.", "error");
            console.error("AJAX call failed:", err);
        }
    });
}
RefreshData();

/* ---------- PAGINATION CONTROLS ---------- */
const nextBtn = root_element.querySelector(".next_distributor_page");
const prevBtn = root_element.querySelector(".prev_distributor_page");
const pageInput = root_element.querySelector(".page_input");
const totalPagesSpan = root_element.querySelector(".total_pages");

nextBtn && nextBtn.addEventListener("click", () => {
    const totalPages = Math.max(1, Math.ceil(filteredData.length / rowsPerPage));
    if (currentPage < totalPages) {
        currentPage++;
        renderCurrentPage();
    }
});
prevBtn && prevBtn.addEventListener("click", () => {
    if (currentPage > 1) {
        currentPage--;
        renderCurrentPage();
    }
});
pageInput && pageInput.addEventListener("change", (e) => {
    const totalPages = Math.max(1, Math.ceil(filteredData.length / rowsPerPage));
    let val = parseInt(e.target.value) || 1;
    if (val < 1) val = 1;
    if (val > totalPages) val = totalPages;
    currentPage = val;
    renderCurrentPage();
});

/* ---------- RENDER PAGE / ROWS ---------- */
function renderCurrentPage() {
    if (!distributor_table_body) return;

    distributor_table_body.innerHTML = '';
    const totalPages = Math.max(1, Math.ceil(filteredData.length / rowsPerPage));

    if (currentPage > totalPages) currentPage = totalPages;
    if (currentPage < 1) currentPage = 1;

    if (totalPagesSpan) totalPagesSpan.innerText = totalPages;
    if (pageInput) {
        pageInput.value = currentPage;
        pageInput.max = totalPages;
    }

    const startIndex = (currentPage - 1) * rowsPerPage;
    const pageData = filteredData.slice(startIndex, startIndex + rowsPerPage);
    updateDistributorsData(pageData, startIndex);
}

function updateDistributorsData(data, startIndex = 0) {
    if (!distributor_table_body) return;

    data.forEach((distributor, idx) => {
        distributor_table_body.appendChild(formatted(distributor, startIndex + idx + 1));
    });
}

/* ---------- ROW FORMATTING ---------- */
function formatted(distributor, srNo) {
    const tr = document.createElement('tr');
    distributorInfo.forEach(info => {
        if (info.name === 'sr_no') {
            const td = document.createElement('td');
            td.innerText = srNo;
            tr.appendChild(td);
        } else {
            tr.appendChild(styledElement(info, distributor));
        }
    });
    return tr;
}

function styledElement(cellInfo, distributor) {
    const cell = document.createElement('td');

    if (cellInfo.title === "Documents Status") {
        const e1 = document.createElement("span");
        if (!distributor["submitted_documents"]) {
            e1.innerText = "pending";
            e1.classList = "badge badge-secondary text-white me-2";
            cell.appendChild(e1);
        } else {
            cell.addEventListener("click", ()=>{
                frappe.set_route("Form", "Distributor Course Documents", distributor["docuemnts_id"]);
            })
            cell.addEventListener("keydown", (event)=>{
                event.preventDefault();
                if(event.code === "Space" || event.keyCode === 32)
                   frappe.set_route("Form", "Distributor Course Documents", distributor["docuemnts_id"]);
            })
            cell.tabIndex = "0";
            cell.classList = "link";
            e1.innerText = "submitted";
            e1.classList = "badge bg-success text-white me-2";
            cell.appendChild(e1);
            const e2 = document.createElement("span");
            e2.innerText = formatTime(distributor.submission_datetime);
            e2.classList.add("datetime");
            cell.appendChild(e2);
        }

    } else if (cellInfo.title === "Distributor Contact") {
        const e1 = document.createElement("span");
        const e2 = document.createElement("span");
        e1.innerText = distributor["distributor_contact_number"] || '';
        e2.innerText = distributor["distributor_email_address"] || '';
        e1.classList.add("distributor_contact_number");
        e2.classList.add("distributor_email_address");
        cell.appendChild(e1);
        cell.appendChild(e2);
        cell.classList.add("small");

    } else if (cellInfo.title === "Course Status") {
        const e1 = document.createElement("span");

        if (distributor["completion_status"] === "Completed") {
            e1.innerText = "Completed";
            e1.classList = "badge bg-success text-white me-2";
            const e2 = document.createElement("span");
            e2.innerText = formatTime(distributor.completed_on);
            e2.classList.add("datetime");
            cell.appendChild(e1);
            cell.appendChild(e2);

        } else if (distributor["completion_status"] === "Active") {
            e1.innerText = "Active";
            let e1_container = document.createElement("div");
            e1.classList = "badge bg-warning text-white me-2";

            e1_container.appendChild(e1);
            const e2 = document.createElement("progress");
            e2.max = 100;
            e2.value = distributor["progress"] || 0;
            e2.classList.add("d-inline-block", "align-middle", "me-2");

            const progressText = document.createElement("span");
            progressText.innerText = `${distributor["progress"] || 0}%`;
            progressText.classList = "pnumber";

            cell.appendChild(e1_container);
            cell.appendChild(e2);
            cell.appendChild(progressText);

        } else if (distributor["completion_status"] === "Re-enrolled") {
            e1.innerText = "Re Enrolled";
            e1.classList = "badge bg-success text-white me-2";
            cell.appendChild(e1);

        } else {
            e1.innerText = "Pending";
            e1.classList = "badge badge-secondary text-white me-2";
            cell.appendChild(e1);
        }

    } else if(cellInfo.title === "Distributor Name"){
        let btn = document.createElement("span");
        btn.innerText = distributor[cellInfo.name] ?? '';
        cell.addEventListener("click" , ()=>{
             frappe.set_route("Form", "Distributor", distributor["distributo_docid"]);
        })
         cell.addEventListener("keydown", (event)=>{
                event.preventDefault();
                if(event.code === "Space" || event.keyCode === 32)
                   frappe.set_route("Form", "Distributor", distributor["distributo_docid"]);
            })
        btn.classList.add("distributor_btn");
        cell.classList = "link";
        cell.tabIndex = "0";
        cell.appendChild(btn);
    }else if (cellInfo.name === "distributor_user_id") {
        if (!distributor[cellInfo.name]) {
            const btn = document.createElement("button");
            btn.innerText = "Send Initial Notifications";
            btn.classList = "btn btn-sm btn-primary";

            btn.addEventListener("click", () => {
                btn.disabled = true;
                btn.innerText = "Sending...";

                frappe.call({
                    method: "lms.lms.user.create_user_from_distributor",
                    args: {
                        distributor_id: distributor["distributo_docid"]
                    },
                    callback: function (r) {
                        if (!r.exc) {
                            frappe.show_alert({ message: "User created & notifications sent!", indicator: "green" });
                            RefreshData(); // reload table
                        } else {
                            frappe.show_alert({ message: "Error creating user", indicator: "red" });
                            btn.disabled = false;
                            btn.innerText = "Send Initial Notifications";
                        }
                    },
                    error: function (err) {
                        frappe.show_alert({ message: "Server Error", indicator: "red" });
                        console.error(err);
                        btn.disabled = false;
                        btn.innerText = "Send Initial Notifications";
                    }
                });
            });

            cell.appendChild(btn);
        } else {
            const span = document.createElement("span");
            span.innerText = "Sent";
            span.classList = "badge bg-success text-white";
            cell.appendChild(span);
    }
    } else if (cellInfo.name === "divisions_meril_company_names") {
    if (distributor[cellInfo.name]) {
        const btn = document.createElement("button");
        btn.innerText = "Show Divisions";
        btn.classList = "btn btn-sm btn-outline-secondary";

        btn.addEventListener("click", () => {
            // Parse the value into rows
            const rawVal = distributor[cellInfo.name];
            const entries = rawVal.split(";").map(item => item.trim()).filter(Boolean);

            let rowsHtml = `
                <table class="table table-bordered table-sm">
                    <thead>
                        <tr>
                            <th>Division</th>
                            <th>Company</th>
                        </tr>
                    </thead>
                    <tbody>
            `;

            entries.forEach(entry => {
                // Example: "Accounts - CE:Company Endo"
                let [divisionPart, company] = entry.split(":");
                divisionPart = divisionPart ? divisionPart.trim() : "";
                company = company ? company.trim() : "";

                rowsHtml += `
                    <tr>
                        <td>${frappe.utils.escape_html(divisionPart)}</td>
                        <td>${frappe.utils.escape_html(company)}</td>
                    </tr>
                `;
            });

            rowsHtml += "</tbody></table>";

            let d = new frappe.ui.Dialog({
                title: "Distributor Divisions & Companies",
                fields: [
                    {
                        fieldtype: "HTML",
                        fieldname: "divisions_html",
                        options: rowsHtml
                    }
                ],
                primary_action_label: "Close",
                primary_action: (values) => d.hide()
            });

            d.show();
        });

        cell.appendChild(btn);
    } else {
        cell.innerText = "-";
    }
    } else if (cellInfo.name === "re_enrollment_count") {
        const count = Number(distributor[cellInfo.name] ?? 0);
        cell.innerText = isNaN(count) ? "0" : String(count);
    } else if (cellInfo.name === "enrollment_history") {
        cell.classList.add("timeline-cell");
        const history = Array.isArray(distributor.enrollment_history)
            ? distributor.enrollment_history
            : safeParseJSON(distributor.enrollment_history);

        if (!history || history.length === 0) {
            cell.innerText = "No enrollments";
            return cell;
        }

        const timelineWrapper = document.createElement("div");
        timelineWrapper.className = "timeline-wrapper";

        history.forEach((entry, idx) => {
            const item = document.createElement("div");
            item.className = "timeline-item";

            const header = document.createElement("div");
            header.className = "timeline-header";
            header.innerText = `${entry.course || 'Course'} (v${entry.enrollment_version || 1})`;
            item.appendChild(header);

            const statusRow = document.createElement("div");
            statusRow.className = "timeline-status";
            const statusBadge = document.createElement("span");
            statusBadge.className = `badge status-${(entry.completion_status || 'pending').toLowerCase().replace(/\s+/g, '-')}`;
            statusBadge.innerText = entry.completion_status || 'Pending';
            statusRow.appendChild(statusBadge);

            if (entry.progress !== null && entry.progress !== undefined) {
                const progressText = document.createElement("span");
                progressText.className = "timeline-progress";
                progressText.innerText = `${entry.progress}%`;
                statusRow.appendChild(progressText);
            }

            if (entry.completed_on) {
                const completedText = document.createElement("span");
                completedText.className = "timeline-date";
                completedText.innerText = formatTime(entry.completed_on);
                statusRow.appendChild(completedText);
            }

            item.appendChild(statusRow);

            if (entry.documents && entry.documents.length) {
                const docsRow = document.createElement("div");
                docsRow.className = "timeline-documents";
                entry.documents.forEach(doc => {
                    const docBadge = document.createElement("span");
                    docBadge.className = "badge document-badge";
                    docBadge.innerText = doc.name || 'Document';
                    const targetId = doc.docid || doc.name;
                    if (targetId) {
                        docBadge.classList.add("document-link");
                        docBadge.tabIndex = 0;
                        const go = () => frappe.set_route("Form", "Distributor Course Documents", targetId);
                        docBadge.addEventListener('click', go);
                        docBadge.addEventListener('keydown', (event) => {
                            if (event.code === "Space" || event.keyCode === 32 || event.code === "Enter" || event.keyCode === 13) {
                                event.preventDefault();
                                go();
                            }
                        });
                    } else if (doc.url) {
                        docBadge.classList.add("document-link");
                        docBadge.tabIndex = 0;
                        docBadge.addEventListener('click', () => {
                            window.open(doc.url, '_blank');
                        });
                        docBadge.addEventListener('keydown', (event) => {
                            if (event.code === "Space" || event.keyCode === 32 || event.code === "Enter" || event.keyCode === 13) {
                                event.preventDefault();
                                window.open(doc.url, '_blank');
                            }
                        });
                    }
                    docsRow.appendChild(docBadge);
                });
                item.appendChild(docsRow);
            }

            timelineWrapper.appendChild(item);
        });

        cell.appendChild(timelineWrapper);
    } else {
        cell.innerText = distributor[cellInfo.name] ?? '';
    }
    return cell;
}

function safeParseJSON(data) {
    if (!data) return null;
    if (Array.isArray(data)) return data;
    try {
        return JSON.parse(data);
    } catch (e) {
        console.warn('Failed to parse JSON:', e, data);
        return null;
    }
}

/* ---------- DATETIME FORMAT ---------- */
function formatTime(datetimeStr) {
    if (!datetimeStr) return '';
    const base = String(datetimeStr).split('.')[0].replace(' ', 'T');
    const date = new Date(base);
    if (isNaN(date)) return String(datetimeStr);
    const monthNames = [
        "January","February","March","April","May","June","July",
        "August","September","October","November","December"
    ];
    const month = monthNames[date.getMonth()];
    const day = String(date.getDate()).padStart(2,'0');
    const year = date.getFullYear();
    let hours = date.getHours();
    const minutes = String(date.getMinutes()).padStart(2,'0');
    const ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;
    hours = String(hours).padStart(2,'0');
    return `${day} ${month} ${year} ${hours}:${minutes} ${ampm}`;
}

/* ---------- SORTING ---------- */
const sortOptions = [
    { label: "No Sorting", value: "" },
    { label: "Distributor Name (A-Z)", value: "distributor_name" },
    { label: "Distributor Company (A-Z)", value: "distributor_company_name" },
    { label: "Document Submission Date (Newest First)", value: "submission_datetime" },
    { label: "Course Completion Date (Newest First)", value: "completed_on" }
];

const sortBySelect = root_element.querySelector("#sortBy");
if (sortBySelect) {
    sortBySelect.innerHTML = '';
    sortOptions.forEach(opt => {
        const o = document.createElement('option');
        o.value = opt.value;
        o.innerText = opt.label;
        sortBySelect.appendChild(o);
    });
    sortBySelect.addEventListener('change', () => {
        applySorting();
        currentPage = 1;
        renderCurrentPage();
    });
}

function applySorting() {
    if (!sortBySelect) return;
    const sortKey = sortBySelect.value;
    if (!sortKey) return;

    filteredData.sort((a, b) => {
        if (sortKey === "distributor_name" || sortKey === "distributor_company_name") {
            const A = (a[sortKey] || "").toString().trim().toLowerCase();
            const B = (b[sortKey] || "").toString().trim().toLowerCase();
            return A.localeCompare(B);
        }
        if (sortKey === "submission_datetime" || sortKey === "completed_on") {
            const da = new Date(a[sortKey] || 0).getTime();
            const db = new Date(b[sortKey] || 0).getTime();
            return db - da;
        }
        return 0;
    });
}

/* ---------- FILTERING ---------- */
function applyFilters() {
    const inputs = Array.from(root_element.querySelectorAll(".column-filter"));
    const filters = {};
    inputs.forEach(inp => {
        const v = inp.value.trim().toLowerCase();
        if (v) filters[inp.dataset.field] = v;
    });

    filteredData = distributorsData.filter(row => {
        return Object.keys(filters).every(field => {
            const searchVal = getSearchableValue(row, field);
            return searchVal.indexOf(filters[field]) !== -1;
        });
    });

    applySorting();
    currentPage = 1;
    renderCurrentPage();
}

function getSearchableValue(row, field) {
    if (!row) return "";

    if (field === "submitted_documents") {
        const status = row.submitted_documents ? "submitted" : "pending";
        const dt = formatTime(row.submission_datetime);
        return `${status} ${dt}`.toLowerCase();
    }

    if (field === "distributor_contact_number") {
        return `${row.distributor_contact_number || ''} ${row.distributor_email_address || ''}`.toLowerCase();
    }

    if (field === "completion_status") {
        let status = "";
        if (row.completion_status === "Completed") status = "completed";
        else if (row.completion_status === "Active") status = "active";
        else if (row.completion_status === "Re-enrolled") status = "re enrolled";
        else status = "pending";
        const date = formatTime(row.completed_on);
        const progress = row.progress ? `${row.progress}%` : "";
        return `${status} ${date} ${progress}`.toLowerCase();
    }

    if (field === "submission_datetime") {
        return (formatTime(row.submission_datetime) || String(row.submission_datetime || '')).toLowerCase();
    }
    if (field === "completed_on") {
        return (formatTime(row.completed_on) || String(row.completed_on || '')).toLowerCase();
    }

    return String(row[field] || "").toLowerCase();
}

/* ---------- UTIL: debounce ---------- */
function debounce(fn, wait) {
    let t;
    return function (...args) {
        clearTimeout(t);
        t = setTimeout(() => fn.apply(this, args), wait);
    };
}



/* ---------- SHOW STATUS MESSAGE ---------- */
function showStatus(message, type = "loading") {
    if (!distributor_table_body) return;

    distributor_table_body.innerHTML = "";
    statusCell.innerText = message;

    // Reset styles
    statusCell.classList.remove("text-danger", "text-primary");
    if (type === "loading") {
        statusCell.classList.add("text-primary");
    } else if (type === "error") {
        statusCell.classList.add("text-danger");
    }

    distributor_table_body.appendChild(statusRow);
}

