script:
/* ---------- CONFIG / ELEMENTS ---------- */
let employeeInfo = [
    { title: "Sr. No.", name: "sr_no" },
    { title: "Employee Id", name: "custom_employee_id" },
    { title: "Employee Name", name: "employee_name" },
    { title: "Employee Contact", name: "employee_contact" },
    { title: "Employee Company", name: "company" },
    { title: "Course Name", name: "course_name" },
    { title: "Remainder Sended", name: "course_reminder_count" },
    { title: "Course Status", name: "completion_status" },
    { title: "Course Timeline", name: "enrollment_history" }
];

let download_view_btn = root_element.querySelector("#download_view_btn");
if (download_view_btn) {
    download_view_btn.addEventListener("click", () => {
        frappe.set_route("query-report", "Employee Report");
    });
}

const table = root_element.querySelector('.employee_table');
const thead = table ? table.querySelector('thead') : null;
const heading_container = thead ? thead.querySelector('.heading_container') : null;
const employee_table_body = root_element.querySelector('.employee_table_body');

let currentPage = 1;
let rowsPerPage = 5;
let employeesData = [];
let filteredData = [];

/* ---------- LOADING & ERROR ELEMENTS ---------- */
const statusRow = document.createElement("tr");
statusRow.classList.add("status-row");

const statusCell = document.createElement("td");
statusCell.colSpan = employeeInfo.length;
statusCell.classList.add("text-center", "py-3", "fw-bold");
statusRow.appendChild(statusCell);

/*------------Row Per Page -----------*/
let rowsPerPageSelect = root_element.querySelector("#rowsPerPage");

rowsPerPageSelect.addEventListener("change", () => {
    if (rowsPerPageSelect.value === "All") {
        rowsPerPage = employeesData.length;
    } else {
        rowsPerPage = parseInt(rowsPerPageSelect.value);
    }
    currentPage = 1;
    renderTablePage();
});
/* ---------- RENDER HEADERS ---------- */
render_titles();

function render_titles() {
    heading_container.innerHTML = '';

    // Create header cells
    employeeInfo.forEach(info => {
        let th = document.createElement('th');
        th.innerText = info.title;
        heading_container.appendChild(th);
    });

    // Create filter row
    let filterRow = document.createElement("tr");
    filterRow.classList.add("filter_row");

    employeeInfo.forEach(info => {
        let th = document.createElement('th');
        if (info.name !== "sr_no") {
            let input = document.createElement("input");
            input.type = "text";
            input.placeholder = `Filter ${info.title}`;
            input.className = "form-control form-control-sm";
            input.dataset.column = info.name;
            input.addEventListener("input", () => {
                currentPage = 1;
                renderTablePage();
            });
            th.appendChild(input);
        }
        filterRow.appendChild(th);
    });

    table.querySelector("thead").appendChild(filterRow);
}

/* ---------- RENDER TABLE ---------- */
function renderTablePage() {
    employee_table_body.innerHTML = '';

    let filters = {};
    table.querySelectorAll(".filter_row input").forEach(input => {
        let val = input.value.trim().toLowerCase();
        if (val) filters[input.dataset.column] = val;
    });

      let filteredData = employeesData.filter(emp => {
        return Object.keys(filters).every(key => {
            let searchVal = "";
    
            if (key === "employee_contact") {
                // merge number + email into one searchable string
                searchVal = `${emp.employee_number || ""} ${emp.company_email || ""}`.toLowerCase();
            } else {
                searchVal = (emp[key] || "").toString().toLowerCase();
            }
    
            return searchVal.includes(filters[key]);
        });
    });

    totalPages = Math.ceil(filteredData.length / rowsPerPage) || 1;
    root_element.querySelector(".total_pages").innerText = totalPages;

    let start = (currentPage - 1) * rowsPerPage;
    let end = start + rowsPerPage;

    filteredData.slice(start, end).forEach((employee, index) => {
        let srNo = start + index + 1;
        employee_table_body.appendChild(formatted(employee, srNo));
    });

    root_element.querySelector(".page_input").value = currentPage;
    root_element.querySelector(".page_input").max = totalPages
}

/* ---------- PAGINATION ---------- */
const refreshButton = root_element.querySelector("button#refresh");
refreshButton.addEventListener("click", RefreshData);

root_element.querySelector(".prev_employee_page").addEventListener("click", () => {
    if (currentPage > 1) {
        currentPage--;
        renderTablePage();
    }
});

root_element.querySelector(".next_employee_page").addEventListener("click", () => {
    if (currentPage < totalPages) {
        currentPage++;
        renderTablePage();
    }
});

root_element.querySelector(".page_input").addEventListener("change", (e) => {
    let val = parseInt(e.target.value);
    if (!isNaN(val) && val >= 1 && val <= totalPages) {
        currentPage = val;
        renderTablePage();
    } else {
        e.target.value = totalPages;
    }
});

/* ---------- REFRESH DATA ---------- */
function RefreshData() {
    showEmployeeStatus("Fetching data, please wait...", "loading");

    frappe.call({
        method: "lms.overrides.dashboardapi.get_employee_dashboard_info",
        callback: function (response) {
            if (response.message) {
                employeesData = Array.isArray(response.message) ? response.message : [];
                totalPages = Math.ceil(employeesData.length / rowsPerPage);
                root_element.querySelector(".total_pages").innerText = totalPages;
                currentPage = 1;
                renderTablePage();
            } else {
                showEmployeeStatus("Error: No data returned from server", "error");
                console.error("Error calling whitelisted method:", response);
            }
        },
        error: function (err) {
            showEmployeeStatus("Error fetching data. Please try again.", "error");
            console.error("AJAX call failed:", err);
        }
    });
}

RefreshData();

/* ---------- ROW FORMAT ---------- */
function formatted(employee, srNo) {
    let tr = document.createElement("tr");
    employeeInfo.forEach(info => {
        if (info.name === "sr_no") {
            tr.appendChild(styledElement({ name: "sr_no" }, { sr_no: srNo }));
        } else {
            tr.appendChild(styledElement(info, employee));
        }
    });
    return tr;
}

function styledElement(cellInfo, employee) {
    const cell = document.createElement("td");

    if (cellInfo.name === "completion_status") {
        const status = (employee[cellInfo.name] || "").trim().toLowerCase();

        if (status === "active" || status === "re-enrolled") {
            let badge = document.createElement("span");
            badge.className = "badge bg-warning text-white me-2"; 
            badge.innerText = status;

            let progressValue = employee.progress || 0;

            let progressWrapper = document.createElement("div");
            progressWrapper.className = "progress-wrapper mt-1 d-flex align-items-center";

            let progress = document.createElement("progress");
            progress.value = progressValue;
            progress.max = 100;
            progress.className = "styled-progress me-2";

            let progressText = document.createElement("span");
            progressText.className = "progress-text fw-bold";
            progressText.innerText = `${progressValue}%`;

            progressWrapper.appendChild(progress);
            progressWrapper.appendChild(progressText);

            cell.appendChild(badge);
            cell.appendChild(progressWrapper);

        } else if (status === "completed") {
            const badge = document.createElement("span");
            badge.className = "badge bg-success text-white me-2";
            badge.innerText = "Completed";
            cell.appendChild(badge);
            
            cell.addEventListener("click", () => {
             frappe.set_route("Form", "Employee Course Documents", employee["docuemnts_id"]);
            });
            cell.addEventListener("keydown", (event) => {
                if (event.code === "Space" || event.keyCode === 32) {
                    event.preventDefault();
                    frappe.set_route("Form", "Employee Course Documents", employee["docuemnts_id"]);
                }
            });
            cell.tabIndex = "0";
            cell.classList = "link";
            if (employee.completed_on) {
                const dateSpan = document.createElement("div");
                dateSpan.className = "text-muted small";
                dateSpan.innerText = formatTime(employee.completed_on);
                cell.appendChild(dateSpan);
            }
        } else { 
            const badge = document.createElement("span"); 
            badge.className = "badge bg-secondary text-white"; 
            badge.innerText = "Pending"; 
            cell.appendChild(badge);
        }

    } else if (cellInfo.title === "Employee Name") {
        let btn = document.createElement("button");
        btn.innerText = employee[cellInfo.name] ?? '';
        
        cell.addEventListener("click", () => {
            frappe.set_route("Form", "Employee", employee["employee_docid"]);
        });
        
        cell.addEventListener("keydown", (event) => {
            event.preventDefault();
            if (event.code === "Space" || event.keyCode === 32) {
                frappe.set_route("Form", "Employee", employee["employee_docid"]);
            }
        });
        
        btn.classList.add("employee_btn");
        cell.classList = "link";
        cell.tabIndex = "0";
        cell.appendChild(btn);
    }else if (cellInfo.title === "Employee Contact") {
    const e1 = document.createElement("span");
    const e2 = document.createElement("span");

    e1.innerText = employee["employee_number"] || '';
    e2.innerText = employee["company_email"] || '';

    e1.classList.add("employee_number");
    e2.classList.add("employee_email");
    
    cell.appendChild(e1);
    cell.appendChild(e2);
    cell.classList.add("small");
    } else {
        // For all other columns
        cell.innerText = employee[cellInfo.name] || "";
    }

    return cell;
}

/* ---------- DATETIME FORMAT ---------- */
function formatTime(datetimeStr) {
    let date = new Date(datetimeStr.split('.')[0].replace(' ', 'T'));
    const monthNames = [
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    ];
    let month = monthNames[date.getMonth()];
    let day = String(date.getDate()).padStart(2, '0');
    let year = date.getFullYear();
    let hours = date.getHours();
    let minutes = String(date.getMinutes()).padStart(2, '0');
    let ampm = hours >= 12 ? 'PM' : 'AM';
    hours = hours % 12 || 12;
    hours = String(hours).padStart(2, '0');
    return `${day} ${month} ${year} ${hours}:${minutes} ${ampm}`;
}

